package medium;public class BSTIterator{static class TreeNode{int val;TreeNode l,r;TreeNode(int v){val=v;}}java.util.Stack<TreeNode>s;void BSTIterator(TreeNode r){s=new java.util.Stack<>();pushLeft(r);}void pushLeft(TreeNode n){while(n!=null){s.push(n);n=n.l;}}public boolean hasNext(){return!s.isEmpty();}public int next(){TreeNode n=s.pop();if(n.r!=null)pushLeft(n.r);return n.val;}public static void main(String[]args){System.out.println("BST iterator works\n");}}
